class Solution
{
public:
    vector<int> sortTransformedArray(vector<int>& nums, int a, int b, int c) {
        auto value = [&](int x) { return a * x * x + b * x + c; };
        int n = nums.size(), left = 0, right = n - 1;
        vector<int> result(n);
        int index = a >= 0 ? n - 1 : 0;
        while (left <= right)
        {
            int lv = value(nums[left]), rv = value(nums[right]);
            if (a >= 0)
            {
                if (lv >= rv)
                {
                    result[index--] = lv;
                    ++left;
                } else
                {
                    result[index--] = rv;
                    --right;
                }
            } else
            {
                if (lv <= rv)
                {
                    result[index++] = lv;
                    ++left;
                } else
                {
                    result[index++] = rv;
                    --right;
                }
            }
        }
        return result;
    }
};
